    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("stage2 official Intel metadata filters source archives drafts and foreign URLs",Metadata);
        yield return("stage2 unavailable Intel release produces a recoverable failure",Unavailable);
        yield return("stage2 Intel download digest cache reuse and corrupt cache preservation",Download);
        yield return("stage2 missing Intel digest remains Unverified and cannot stage",MissingDigest);
        yield return("stage2 Intel staging allowlist notices and unknown versions stay non-installable",Allowlist);
        yield return("stage2 corrupt Intel ZIP is rejected",Corrupt);
        yield return("stage2 Intel ZIP traversal absolute ADS and reserved paths are rejected",UnsafePaths);
        yield return("stage2 Intel ZIP duplicate paths links and expansion limits are rejected",Duplicates);
        yield return("stage2 interrupted cancelled and wrong-digest Intel downloads leave no partial archive",Interrupted);
        yield return("stage2 real official Intel SDK stages authentic files and reuses pinned Wizard cache",Genuine);
        yield return("stage2 NVIDIA target-layout guard remains blocked and destination specific",NvidiaGuard);
        yield return("stage2 components provider navigation and loaded localized Intel view",Controls);
    }
    private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    private static void Reject(Action action){try{action();}catch(Exception ex)when(ex is IOException or InvalidDataException or OperationCanceledException or HttpRequestException){return;}throw new Exception("Expected refusal");}
    private static string Temp(){var path=Path.Combine(AppContext.BaseDirectory,"Stage2-Intel-Checks",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    private static byte[] Zip(params (string Name,string Body)[] files){using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true))foreach(var file in files){var entry=zip.CreateEntry(file.Name);using var writer=new StreamWriter(entry.Open());writer.Write(file.Body);}return output.ToArray();}
    private static IntelSdkAsset Asset(byte[] bytes,string? digest="computed")=>new("XeSS_SDK_9.0.0.zip","https://github.com/intel/xess/releases/download/v9.0.0/XeSS_SDK_9.0.0.zip",bytes.Length,digest=="computed"?Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant():digest,"v9.0.0","Synthetic test metadata",DateTimeOffset.UtcNow,"https://github.com/intel/xess/releases/tag/v9.0.0","Test notes",true,false);
    private sealed class Handler(Func<HttpRequestMessage,HttpResponseMessage> send):HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();Calls++;var response=send(request);response.RequestMessage??=request;return Task.FromResult(response);}}
    private static HttpResponseMessage Bytes(byte[] bytes)=>new(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)};
    private static IntelSdkPackageService Package(byte[] bytes,string? root=null)=>new(root??Temp(),new HttpClient(new Handler(_=>Bytes(bytes))));
    private static IntelSdkStage Prepare(IntelSdkPackageService service,byte[] bytes){var asset=Asset(bytes);service.DownloadAsync(asset).GetAwaiter().GetResult();return service.StageAsync(asset).GetAwaiter().GetResult();}
    private static void Metadata()
    {
        var good=Asset([1,2]);object Release(string tag,bool draft,params object[] assets)=>new{tag_name=tag,name=tag,html_url="https://github.com/intel/xess/releases/tag/"+tag,published_at="2026-10-01T00:00:00Z",body="Original notes",draft,prerelease=false,assets};
        var payload=JsonSerializer.Serialize(new[]{Release("v9.0.0",false,new{name=good.Name,browser_download_url=good.DownloadUrl,size=good.Size,digest="sha256:"+good.Sha256},new{name="Source code.zip",browser_download_url=good.DownloadUrl,size=good.Size},new{name=good.Name,browser_download_url="https://mirror.invalid/file.zip",size=good.Size}),Release("v8.0.0",true,new{name=good.Name,browser_download_url=good.DownloadUrl,size=good.Size})});
        using var doc=JsonDocument.Parse(payload);var parsed=IntelSdkCatalogClient.Parse(doc.RootElement,"v9.0.0");Check(parsed.Count==1&&parsed[0].OfficialLatest&&parsed[0].Tag=="v9.0.0","Untrusted archive offered or latest lost");Check(parsed[0].Sha256==good.Sha256,"Official digest lost");
        var client=new IntelSdkCatalogClient(new HttpClient(new Handler(request=>Bytes(Encoding.UTF8.GetBytes(request.RequestUri!.AbsolutePath.EndsWith("/latest")?"{\"tag_name\":\"v9.0.0\"}":payload)))));Check(client.GetAsync().GetAwaiter().GetResult().Assets.Single().OfficialLatest,"Official latest lookup failed");
        var redirected=new IntelSdkCatalogClient(new HttpClient(new Handler(_=>new(HttpStatusCode.OK){RequestMessage=new(HttpMethod.Get,"https://mirror.invalid/releases"),Content=new StringContent("[]")})));Reject(()=>redirected.GetAsync().GetAwaiter().GetResult());
        Reject(()=>IntelSdkCatalogClient.Validate(good with{DownloadUrl=good.DownloadUrl+"?redirect=foreign"}));Reject(()=>IntelSdkCatalogClient.Validate(good with{Name="../XeSS_SDK_9.zip"}));
    }
    private static void Unavailable(){var http=new HttpClient(new Handler(_=>new(HttpStatusCode.NotFound)));Reject(()=>new IntelSdkCatalogClient(http).GetAsync().GetAwaiter().GetResult());}
    private static void Download(){var bytes=Zip(("LICENSE.txt","notice"));var handler=new Handler(_=>Bytes(bytes));var service=new IntelSdkPackageService(Temp(),new HttpClient(handler));var asset=Asset(bytes);var first=service.DownloadAsync(asset).GetAwaiter().GetResult();Check(first.OfficialDigestVerified,"Valid hash not verified");Check(service.DownloadAsync(asset).GetAwaiter().GetResult().Path==first.Path&&handler.Calls==1,"Cache downloaded again");File.WriteAllText(first.Path,"external");Reject(()=>service.DownloadAsync(asset).GetAwaiter().GetResult());Check(File.ReadAllText(first.Path)=="external","Corrupt cache overwritten");}
    private static void MissingDigest(){var bytes=Zip(("LICENSE.txt","notice"));var service=Package(bytes);var asset=Asset(bytes,null);var download=service.DownloadAsync(asset).GetAwaiter().GetResult();Check(!download.OfficialDigestVerified&&download.Sha256.Length==64,"Missing digest fabricated verification");Reject(()=>service.StageAsync(asset).GetAwaiter().GetResult());Check(!Directory.Exists(service.Runtime.PackageDirectory),"Unverified SDK reached Wizard cache");}
    private static void Allowlist(){var bytes=Zip(("bin/libxess_fg.dll","not a PE"),("bin/libxell.dll","not a PE"),("bin/libxess.dll","separate SR"),("development/bin/libxell.dll","debug"),("LICENSE.txt","license"),("third-party-programs.txt","notice"),("samples/LICENSE.md","sample license"),("run.exe","never run"));var service=Package(bytes);var stage=Prepare(service,bytes);Check(stage.Files.Count==5&&stage.Skipped==3,"Wrong allowlist");Check(stage.Files.Count(f=>f.Version=="Unknown version")==2&&!stage.CatalogCompatible,"Unknown DLL marked compatible");Check(!File.Exists(Path.Combine(stage.Directory,"run.exe"))&&!File.Exists(Path.Combine(stage.Directory,"bin","libxess.dll")),"Unknown component extracted");Reject(()=>service.PrepareCompatibleAsync(stage).GetAwaiter().GetResult());Check(!Directory.Exists(service.Runtime.PackageDirectory),"Unverified runtime was promoted");}
    private static void Corrupt(){var bytes=Encoding.UTF8.GetBytes("not a ZIP");var service=Package(bytes);service.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult();Reject(()=>service.StageAsync(Asset(bytes)).GetAwaiter().GetResult());Check(!Directory.Exists(service.Staging)||!Directory.EnumerateFileSystemEntries(service.Staging).Any(),"Failed stage left a promoted directory");}
    private static void UnsafePaths(){foreach(var path in new[]{"../outside.dll","/outside.dll","C:/outside.dll","bin/file.dll:stream","bin\\escape.dll","NUL.txt","bin/./libxell.dll"}){var bytes=Zip((path,"bad"),("LICENSE.txt","valid"));var service=Package(bytes);service.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult();Reject(()=>service.StageAsync(Asset(bytes)).GetAwaiter().GetResult());}}
    private static void Duplicates(){
        var bytes=Zip(("LICENSE.txt","one"),("license.TXT","two"));var service=Package(bytes);service.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult();Reject(()=>service.StageAsync(Asset(bytes)).GetAwaiter().GetResult());
        using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){var entry=zip.CreateEntry("LICENSE.txt");entry.ExternalAttributes=unchecked((int)0xA1FF0000);using var writer=new StreamWriter(entry.Open());writer.Write("outside");}bytes=output.ToArray();service=Package(bytes);service.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult();Reject(()=>service.StageAsync(Asset(bytes)).GetAwaiter().GetResult());
        bytes=Zip(("huge.bin","x"));for(var i=0;i<bytes.Length-28;i++)if(BitConverter.ToUInt32(bytes,i)==0x02014b50){BitConverter.GetBytes(536870913u).CopyTo(bytes,i+24);break;}service=Package(bytes);service.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult();Reject(()=>service.StageAsync(Asset(bytes)).GetAwaiter().GetResult());
    }
    private sealed class BrokenStream(byte[] bytes):MemoryStream(bytes){private bool sent;public override ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken token=default){if(sent)throw new IOException("Injected disconnect");sent=true;return base.ReadAsync(buffer,token);}}
    private static void Interrupted(){
        var bytes=Zip(("LICENSE.txt","license"));var root=Temp();var handler=new Handler(_=>new(HttpStatusCode.OK){Content=new StreamContent(new BrokenStream(bytes))});var service=new IntelSdkPackageService(root,new HttpClient(handler));Reject(()=>service.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult());Check(!Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories).Any(),"Interrupted bytes retained");
        var retry=Package(bytes,root);var result=retry.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult();Check(result.OfficialDigestVerified,"Retry failed");
        var cancelled=Package(bytes);Reject(()=>cancelled.DownloadAsync(Asset(bytes),token:new CancellationToken(true)).GetAwaiter().GetResult());Check(!Directory.EnumerateFiles(cancelled.Store,"*",SearchOption.AllDirectories).Any(),"Cancelled download retained partial data");
        var wrong=Package(bytes);Reject(()=>wrong.DownloadAsync(Asset(bytes,new string('a',64))).GetAwaiter().GetResult());Check(!Directory.EnumerateFiles(wrong.Store,"*",SearchOption.AllDirectories).Any(),"Wrong digest retained output");
        var redirected=new IntelSdkPackageService(Temp(),new HttpClient(new Handler(_=>new(HttpStatusCode.OK){RequestMessage=new(HttpMethod.Get,"https://mirror.invalid/payload.zip"),Content=new ByteArrayContent(bytes)})));Reject(()=>redirected.DownloadAsync(Asset(bytes)).GetAwaiter().GetResult());
    }
    private static void Genuine(){
        var archive=Environment.GetEnvironmentVariable("RENODX_TEST_INTEL_SDK_ARCHIVE");if(string.IsNullOrWhiteSpace(archive)||!File.Exists(archive))throw new SkipCheckException("Provide the isolated official Intel SDK fixture; no network is required by tests.");
        var service=new IntelSdkPackageService(Temp(),new HttpClient(new Handler(_=>throw new Exception("Unexpected network access"))));var asset=new IntelSdkAsset("XeSS_SDK_3.0.2.zip","https://github.com/intel/xess/releases/download/v3.0.2/XeSS_SDK_3.0.2.zip",76839749,"88b8a373f30e33f3558a77a93e634f11b8132fc3047ea1a8edeead32b8471990","v3.0.2","XeSS SDK 3.0.2",null,"https://github.com/intel/xess/releases/tag/v3.0.2","Official snapshot",true,false);
        var target=Path.Combine(service.Downloads,asset.Tag,asset.Name);Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Copy(archive,target);Check(service.DownloadAsync(asset).GetAwaiter().GetResult().OfficialDigestVerified,"Real archive digest failed");var stage=service.StageAsync(asset).GetAwaiter().GetResult();Check(stage.CatalogCompatible,"Real runtime files differ from pinned catalog");Check(stage.Files.Single(f=>f.RelativePath=="bin/libxess_fg.dll").Version=="1.3.1.78"&&stage.Files.Single(f=>f.RelativePath=="bin/libxell.dll").Version=="1.3.2.10","DLL version inferred from SDK tag");Check(stage.Files.Count==5&&stage.Files.Any(f=>f.RelativePath=="third-party-programs.txt"),"Real notices missing");var package=service.PrepareCompatibleAsync(stage).GetAwaiter().GetResult();Check(package.DirectoryPath==service.Runtime.PackageDirectory&&IntelRuntimeService.Assets.All(a=>File.Exists(Path.Combine(package.DirectoryPath,a.Name))),"Compatible files not shared with Wizard");Reject(()=>service.Runtime.PreviewAsync(new(stage.Directory),Temp(),"not-game.exe",Temp(),true).GetAwaiter().GetResult());
        Console.WriteLine($"EVIDENCE official SDK 3.0.2: {stage.Files.Count} staged, {stage.Skipped} skipped; FG 1.3.1.78, XeLL 1.3.2.10; exact four-file pinned catalog matched; no game installation.");
        File.WriteAllText(stage.Files.First().Path,"external");Reject(()=>service.PrepareCompatibleAsync(stage).GetAwaiter().GetResult());
    }
    private static void NvidiaGuard(){var root=Temp();var target=Path.Combine(root,"selected");Directory.CreateDirectory(target);var exe=Path.Combine(target,"own-test.exe");File.WriteAllText(exe,"isolated test");Directory.CreateDirectory(Path.Combine(root,"other"));File.WriteAllText(Path.Combine(root,"other","sl.interposer.dll"),"not in selected destination");var installer=new AdvancedRuntimeInstaller(Temp(),Temp(),new BackupRestoreService(Temp()));try{installer.PreviewAsync(null!,root,exe,target,true).GetAwaiter().GetResult();throw new Exception("Unsupported layout allowed");}catch(InvalidDataException ex){Check(ex.Message.Contains("sl.interposer.dll"),"Wrong target directory checked");var display=MainWindow.ExplainRuntimeError(ex.Message);Check(display.Contains("only the layout")&&display.Contains("cannot create game"),"Message implies universal integration absence");}Check(Directory.EnumerateFiles(target).SequenceEqual(new[]{exe}),"Guard wrote game files");}
    private static void Controls()=>WpfCheckHost.Run(()=>{
        var main=new MainWindow();const BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;var type=typeof(MainWindow);main.Loaded-=type.GetMethod("Window_Loaded",flags)!.CreateDelegate<RoutedEventHandler>(main);main.Show();var trace=new StringWriter();var listener=new System.Diagnostics.TextWriterTraceListener(trace);System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Add(listener);
        try{type.GetMethod("NvidiaComponents_Click",flags)!.Invoke(main,[main,new RoutedEventArgs()]);var view=(IntelSdkManagerView)main.FindName("IntelSdkView");type.GetMethod("SetComponentsProvider",flags)!.Invoke(main,[true]);Check(view.Visibility==Visibility.Visible&&((FrameworkElement)main.FindName("NvidiaManagerBody")).Visibility==Visibility.Collapsed,"Provider switching failed");
            var row=Activator.CreateInstance(type.GetNestedType("IntelSdkRow",BindingFlags.NonPublic)!,[Asset([1,2])])!;view.ReleasesList.ItemsSource=new[]{row};
            type.GetMethod("AddIntelFile",flags)!.Invoke(main,["libxess_fg.dll","Unknown version","Experimental / Unverified","Own test details"]);
            foreach(var culture in UiLocalization.Cultures){LocalizedPresentation.Language.SetCulture(culture,false);LocalizedPresentation.RefreshGeneratedItems(main);main.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);Check(((StackPanel)((Button)main.FindName("NvidiaComponentsNavButton")).Content).Children.OfType<TextBlock>().Last().Text==LocalizedPresentation.Language.Lookup("Components / SDK"),"Top tab not localized");Check(view.PrepareCompatibleButton.Content as string==LocalizedPresentation.Language.Lookup("Prepare compatible runtime"),"Intel controls not localized");Check(Descendants(view).OfType<TextBlock>().Any(t=>t.Text==LocalizedPresentation.Language.Lookup("Unknown version")+" · "+LocalizedPresentation.Language.Lookup("Experimental / Unverified")),"Late local file card was not localized");}
            type.GetMethod("SetComponentsProvider",flags)!.Invoke(main,[false]);Check(view.Visibility==Visibility.Collapsed&&((FrameworkElement)main.FindName("NvidiaManagerBody")).Visibility==Visibility.Visible,"NVIDIA tools lost");listener.Flush();Check(!trace.ToString().Contains("Error:"),"WPF binding error: "+trace);
        }finally{System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Remove(listener);main.Close();}
    });
    private static IEnumerable<DependencyObject> Descendants(DependencyObject root){for(var i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++){var child=System.Windows.Media.VisualTreeHelper.GetChild(root,i);yield return child;foreach(var nested in Descendants(child))yield return nested;}}
